"""Complete 32 original oncologic emergency questions."""
from create_oncology_compressive_emergencies import rows,q,FN,NS,TL,RA,HC,MS,SV,ref
from qbank_authoring import finalize

q('A patient with lymphoma has hypercalcemia, suppressed PTH and elevated calcitriol. Which treatment addresses this particular mechanism?', 'Glucocorticoid treatment to reduce calcitriol production, with other urgent calcium measures as needed',[
 ('Cinacalcet as the sole routine treatment of every non-PTH-mediated case','It primarily targets calcium-sensing/PTH physiology and is not the key mechanism here.'),('Calcium and calcitriol supplementation','This can worsen the hypercalcemia.'),('A thiazide to increase urinary calcium conservation','That can aggravate the problem.')],
 'Hypercalcemia of malignancy has several mechanisms','**Some lymphomas increase extrarenal calcitriol production.**',['Glucocorticoids can reduce that production and intestinal calcium absorption.','PTHrP-mediated and osteolytic disease have different primary mechanisms.'],'**Treat severity and the malignancy as well as the mechanism.**',['Hydration and antiresorptive treatment may still be required.','Monitor glucose, infection risk and calcium response.'],[['PTH','Suppressed'],['Calcitriol','Elevated'],['Mechanism-directed option','Glucocorticoid']],[HC],style='clinical_scenario')

q('Hypercalcemia of malignancy recurs despite recent IV bisphosphonate treatment. Which additional antiresorptive option is guideline-supported for consideration?', 'Denosumab',[
 ('Calcitonin alone indefinitely','Tachyphylaxis limits prolonged control.'),('Routine oral calcium loading','This does not treat hypercalcemia.'),('Repeat unlimited bisphosphonate doses without renal or timing review','Redosing requires an appropriate risk/timing assessment.')],
 'Refractory disease may need a different antiresorptive mechanism','**RANKL inhibition can reduce osteoclast activity.**',['Monitor for hypocalcemia, especially with kidney impairment.','Correct relevant deficiencies cautiously within the calcium-management context.'],'**Reassess the mechanism and tumor control.**',['Do not assume every recurrence is due to the same pathway.','Plan monitoring of calcium, phosphate and magnesium.'],[['Prior treatment','IV bisphosphonate'],['Alternative mechanism','RANKL inhibition'],['Monitoring','Hypocalcemia and mineral changes']],[HC],style='clinical_scenario')

q('A cancer patient has hypotension, elevated JVP and echocardiographic evidence of hemodynamically significant pericardial compression. Which action is appropriate?', 'Urgent specialist drainage and hemodynamic support for tamponade',[
 ('Wait for final cytology before relieving the pressure','Instability requires treatment before etiological completion.'),('Give aggressive diuresis as the sole initial treatment','Reducing filling can worsen tamponade physiology.'),('Assume every malignant effusion must be large to be dangerous','Accumulation rate and compliance affect hemodynamic impact.')],
 'Pressure effect takes priority over proving malignant cells','**Tamponade is a physiological diagnosis supported by clinical and echo findings.**',['A rapidly accumulating smaller effusion can be dangerous.','Plan drainage technique and recurrence management according to the case.'],'**Obtain diagnostic material while treating the emergency.**',['Continue oncological evaluation after stabilization.','Do not equate effusion size alone with severity.'],[['Immediate problem','Impaired filling'],['Treatment','Urgent appropriate drainage'],['Later','Cause and recurrence plan']],[ref('NCI cardiopulmonary syndromes professional summary','https://www.cancer.gov/about-cancer/treatment/side-effects/cardiopulmonary-hp-pdq')],style='clinical_scenario')

q('Brain metastases cause headache, focal deficits and imaging-confirmed vasogenic edema. Which medication is commonly used for short-term symptomatic edema control?', 'Dexamethasone at an appropriate symptom-based dose',[
 ('Routine prophylactic steroid at high dose for every asymptomatic metastasis','Benefits and harms require clinical indication.'),('A diuretic alone as definitive tumor treatment','This does not provide tumor-directed control.'),('Long-term maximal steroids without reassessment','Adverse effects and tapering needs require review.')],
 'Treat edema while planning definitive disease control','**Glucocorticoids can reduce vasogenic edema and associated symptoms.**',['Use the lowest effective dose and an individualized taper.','Surgery, radiosurgery, radiation or systemic therapy depends on tumor and patient factors.'],'**Assess urgent mass effect and seizure needs.**',['Do not use medication to delay necessary neurosurgical evaluation.','Monitor infection, glucose, mood and proximal weakness.'],[['Steroid role','Symptomatic edema'],['Definitive care','Tumor/lesion strategy'],['Safety','Dose and duration review']],[ref('ASCO/SNO brain metastases steroid guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC7098828/')],style='clinical_scenario')

q('Imaging suggests primary CNS lymphoma, and the patient is neurologically stable without dangerous mass effect. Which biopsy principle is important?', 'Avoid corticosteroids before diagnostic sampling when clinically feasible because they can reduce biopsy yield',[
 ('Give prolonged high-dose steroids to every patient before biopsy regardless of stability','Lympholytic effects can obscure diagnosis.'),('Never give steroids even if life-threatening herniation develops','Immediate danger can override the preferred diagnostic sequence.'),('A steroid response confirms lymphoma without tissue','Other lesions can respond and histological confirmation is generally needed.')],
 'A treatment response can erase diagnostic evidence','**Lymphoma cells may regress after corticosteroid exposure.**',['Discuss timing promptly with the specialist team.','Patient safety remains the overriding priority in unstable mass effect.'],'**Obtain timely tissue and then use the definitive lymphoma pathway.**',['Do not use this principle as a reason to delay urgent treatment of impending herniation.','Document any prior steroid exposure.'],[['Stable suspected PCNSL','Sample before steroid when feasible'],['Dangerous mass effect','Treat urgently'],['Diagnosis','Tissue rather than response alone']],[ref('EHA–ESMO primary CNS lymphoma guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC11148853/')],style='clinical_scenario')

q('A patient with acute leukemia has severe dyspnea and neurological symptoms with a very high circulating blast count. Which principle is correct?', 'Suspected leukostasis requires urgent specialist cytoreduction and supportive care based on symptoms, not a universal count cutoff alone',[
 ('Symptoms can be ignored until WBC exceeds exactly 100 × 10^9/L','Leukostasis can occur at lower counts, especially with myeloid disease.'),('A high count alone proves the same clinical syndrome in every leukemia','Cell type and clinical findings matter.'),('Routine large RBC transfusion should precede all assessment regardless of hemoglobin or viscosity','Transfusion decisions require care because viscosity can worsen.')],
 'Hyperleukocytosis and leukostasis are related but not identical','**Microvascular complications depend on cell biology and burden.**',['Assess respiratory, neurological and metabolic complications.','TLS risk can increase during cytoreduction.'],'**Use urgent hematology-directed treatment.**',['Hydration and transfusion must be individualized.','Leukapheresis is selected rather than a universal substitute for definitive therapy.'],[['Count','Risk marker'],['Leukostasis','Clinical organ syndrome'],['Treatment','Urgent cytoreduction/support']],[ref('European LeukemiaNet adult AML recommendations','https://doi.org/10.1182/blood.2022016867')],style='clinical_scenario')

q('A patient has suspected acute promyelocytic leukemia with severe consumptive coagulopathy. Which principle is appropriate while confirmatory testing is expedited?', 'Start ATRA promptly on strong suspicion and support coagulation under urgent hematology care',[
 ('Wait several days for final genetics before any APL-directed treatment','Early hemorrhagic death is a major danger.'),('Treat with anticoagulation alone as the definitive leukemia strategy','This does not address the underlying disease and can add bleeding risk.'),('Assume the coagulopathy excludes APL','Coagulopathy is a classic emergency feature.')],
 'APL is a treat-first diagnostic emergency','**Rapid differentiation therapy can be life-saving.**',['Send urgent molecular/cytogenetic confirmation.','Provide aggressive appropriate platelet/fibrinogen and other hemostatic support.'],'**Use a specialist APL pathway.**',['Avoid unnecessary invasive procedures during uncontrolled coagulopathy.','Monitor for differentiation syndrome as treatment begins.'],[['Suspicion','APL plus bleeding/coagulopathy'],['Immediate therapy','ATRA'],['Parallel care','Confirmation and hemostatic support']],[ref('European LeukemiaNet APL management recommendations','https://pmc.ncbi.nlm.nih.gov/articles/PMC6509567/')],style='clinical_scenario')

q('A patient with pelvic malignancy develops anuria, hyperkalemia and bilateral hydronephrosis. Which intervention addresses the reversible anatomical cause?', 'Urgent urinary decompression using an appropriate stent or nephrostomy strategy',[
 ('Wait for chemotherapy response while severe obstruction persists','Urgent physiological and anatomical treatment may be needed.'),('Give diuretics alone to force urine through complete obstruction','This does not reliably relieve the block.'),('Dialysis permanently removes the need to assess obstruction','Dialysis can treat complications but does not correct the anatomical cause.')],
 'Support and source relief are complementary','**Malignant obstruction can cause severe postrenal AKI.**',['Treat dangerous potassium and other complications immediately.','Route and goals of decompression depend on anatomy, infection, prognosis and preference.'],'**Coordinate urology/interventional and renal care.**',['Monitor post-obstructive diuresis and electrolyte shifts.','Discuss expected benefit and burden in the wider cancer plan.'],[['Problem','Bilateral outflow obstruction'],['Cause treatment','Decompression'],['Support','Electrolyte/RRT care as needed']],[ref('NICE acute kidney injury: obstructive causes','https://www.nice.org.uk/guidance/ng148/chapter/Recommendations')],style='clinical_scenario')

if __name__=='__main__':finalize('Oncology',2,'Oncologic Emergencies','onco-emergencies',rows,32)
